typedef void (*turn_handler)(void *, bool);
struct turn_slot { short adjustment; unsigned short padding; turn_handler function; };
struct panel_vtable { char padding[24]; turn_slot turn_on; };
class PanelQuad {
    char padding[404];
    panel_vtable *vtable;
public:
    void TurnOn(bool on)
    {
        turn_slot &slot = vtable->turn_on;
        slot.function((char *)this + slot.adjustment, on);
    }
};
class HighScoreFrontEnd {
    char padding[0x240];
    PanelQuad* arrows[2][2];
    char padding2[0x30];
    bool in_game;
    char padding3[0xd7];
    PanelQuad* fade;
    PanelQuad* lines[19];
public:
    void TurnHighScore(bool on);
};
void HighScoreFrontEnd::TurnHighScore(bool on)
{
	arrows[0][1]->TurnOn(false);
	arrows[1][1]->TurnOn(false);
	arrows[0][0]->TurnOn(!in_game && on);
	arrows[1][0]->TurnOn(!in_game && on);

	if(in_game)
	{
		for(int i=0; i<19; i++)
			lines[i]->TurnOn(on);
		fade->TurnOn(on);
	}
}
